  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
