-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
violation as (
  select
    rc.seed_oid,
    count(distinct rc.nspname) filter (where rc.lvl <= 1 and rc.mask = 0) = 2 as direct,
    count(distinct rc.nspname) filter (where rc.lvl <= 2 and rc.mask = 0) = 2 as nested,
    count(distinct rc.nspname) filter (where rc.mask & 5 = 0) = 2 as by_function,
    count(distinct rc.nspname) filter (where rc.mask & 4 = 0) = 2 as by_operator
  from reach as rc
  group by rc.seed_oid
  having count(distinct rc.nspname) = 2
)
select
  case
    when r.in_system_schema then 'system_schema_view'
    when v.direct then 'direct_join'
    when v.nested then 'nested_view'
    when v.by_function then 'via_function'
    when v.by_operator then 'via_operator'
    else 'via_domain'
  end::text as branch,
  format('%I.%I', r.nspname, r.relname)::text as object,
  (
    case when r.relkind = 'm' then 'materialized view' else 'view' end
    || case when r.in_system_schema then ' in a system schema' else '' end
    || ' reaches quality and integrity '
    || case
      when v.direct then 'through the relations it reads directly'
      when v.nested then 'through nested views'
      when v.by_function then 'through a function'
      when v.by_operator then 'through an operator'
      else 'through a domain'
    end
  )::text as detail
from violation as v
join root as r on r.oid = v.seed_oid
) as v where v.branch = 'via_function'
$q$, 'MT-5a.via_function: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5a.system_schema_view: a view in _realtime, a system-list schema where postgres can create objects, that joins
-- a quality table and an integrity table. The view is owned by a role that postgres created, so postgres holds
-- ADMIN OPTION on it without INHERIT or SET (PostgreSQL 16+): postgres is a MEMBER of the owner, not able to SET
-- ROLE to it. postgres grants itself SET only long enough to create the view, then revokes that grant.
create table quality.mt_5a_score (session_id uuid, points int);
create table integrity.mt_5a_signal (session_id uuid, band text);
create role mt_5a_owner nologin;
grant mt_5a_owner to postgres with inherit false, set true;
grant create on schema _realtime to mt_5a_owner;
grant usage on schema quality, integrity to mt_5a_owner;
set role mt_5a_owner;
create view _realtime.mt_5a_blend with (security_invoker = true) as
select s.session_id, s.points, g.band
from quality.mt_5a_score as s
join integrity.mt_5a_signal as g on g.session_id = s.session_id;
reset role;
revoke mt_5a_owner from postgres;
reset role;
