),
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, r.oid
  from root as r
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
violation as (
  select
    rc.seed_oid,
    count(distinct rc.nspname) filter (where rc.how = 'dep' and rc.mask & 8 = 0) = 2 as by_depend,
    count(distinct rc.nspname) filter (where rc.how in ('dep', 'src') and rc.mask & 8 = 0) = 2 as by_prosrc,
    count(distinct rc.nspname) filter (where rc.mask & 8 = 0) = 2 as by_config
  from reach as rc
  group by rc.seed_oid
  having count(distinct rc.nspname) = 2
)
select
  case
    when r.in_system_schema then 'system_schema_function'
    when v.by_depend then 'begin_atomic_depend'
    when v.by_prosrc then 'prosrc_reference'
    when v.by_config then 'proconfig_search_path'
    else 'prosrc_call'
  end::text as branch,
  r.qualified_name as object,
  (
    'function '
    || case when r.in_system_schema then 'in a system schema ' else '' end
    || 'reaches quality and integrity '
    || case
      when v.by_depend then 'through pg_depend'
      when v.by_prosrc then 'through a schema named in a function body'
      when v.by_config then 'through a function search_path'
      else 'through a call named in a function body'
    end
  )::text as detail
from violation as v
join root as r on r.oid = v.seed_oid
) as v where v.branch = 'proconfig_search_path'
$q$, 'MT-5b.proconfig_search_path: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5b.system_schema_function: a plpgsql function in _realtime, a system-list schema where postgres can create
-- objects, that reads a quality table and an integrity table.
create table quality.mt_5b_score (session_id uuid, points int);
create table integrity.mt_5b_signal (session_id uuid, band text);
create function _realtime.mt_5b_blend(p_session uuid) returns text
language plpgsql
stable
as $$
begin
  return (
    select s.points::text || g.band
    from quality.mt_5b_score as s
    join integrity.mt_5b_signal as g on g.session_id = s.session_id
    where s.session_id = p_session
  );
end
$$;
reset role;
select isnt_empty($q$
select * from (
-- MT-5b (spec specs/m0-foundations.md §8.5, rule 1): a function (any prokind), not an extension member, in any
-- non-system schema or in a system-list schema where a migration can still create objects (escape_schema below,
-- when postgres is a member of its owner), that reaches both quality and integrity by the MT-5a rule. plpgsql
-- bodies are not in pg_depend, so prosrc and proconfig are read as well. The closure (shared:graph and
-- shared:closure below, the same text in MT-5a, 5b, 5c and 5d) starts at the function and follows its pg_depend
-- rows, every call its body names (schema.name(, or an unqualified name( resolved through its search_path
-- setting), the rules of views (pg_rewrite, skipping a rule's reference to its own relation) and other functions,
-- recursively. A node reaches a schema when it lives there (a relation also reaches the schema of every member of
-- every inheritance tree it belongs to: INHERITS children and partitions alike, wherever they live), when it is a
-- type or schema ref there, or, for a function, when its prosrc outside SQL comments names it (quality. or
-- "quality"., or 'quality' as an argument of format(), quote_ident() or set_config(), case-insensitive) or its
-- proconfig search_path lists it.
-- Branches, first match wins: system_schema_function (the function lives in a system-list schema),
-- begin_atomic_depend (pg_depend alone reaches both, as for a BEGIN ATOMIC body), prosrc_reference (a prosrc match
-- is needed, no proconfig, no call), proconfig_search_path (a proconfig match is needed, no call), prosrc_call (a
-- call named in a function body is needed).
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
root as (
  select
    p.oid,
    format('%I.%I(%s)', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid))::text as qualified_name,
    n.oid in (select es.oid from escape_schema as es) as in_system_schema
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where (
      (
        n.nspname not in (
          'pg_catalog', 'information_schema', 'auth', 'storage', 'extensions', 'realtime', '_realtime',
          'graphql', 'graphql_public', 'supabase_functions', 'supabase_migrations', 'vault', 'pgsodium',
          'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
        )
        and n.nspname !~ '^pg_toast(_temp_[0-9]+)?$'
        and n.nspname !~ '^pg_temp_[0-9]+$'
      )
      or (
        n.oid in (select es.oid from escape_schema as es)
        and pg_has_role('postgres', p.proowner, 'MEMBER')
      )
    )
    and not exists (
      select 1
      from pg_depend as d
      join pg_extension as x on x.oid = d.refobjid
      where d.classid = 'pg_proc'::regclass
        and d.objid = p.oid
        and d.refclassid = 'pg_extension'::regclass
        and d.deptype = 'e'
        and x.extnamespace = p.pronamespace
    )
),
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, r.oid
  from root as r
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
violation as (
  select
    rc.seed_oid,
    count(distinct rc.nspname) filter (where rc.how = 'dep' and rc.mask & 8 = 0) = 2 as by_depend,
    count(distinct rc.nspname) filter (where rc.how in ('dep', 'src') and rc.mask & 8 = 0) = 2 as by_prosrc,
    count(distinct rc.nspname) filter (where rc.mask & 8 = 0) = 2 as by_config
  from reach as rc
  group by rc.seed_oid
  having count(distinct rc.nspname) = 2
)
select
  case
    when r.in_system_schema then 'system_schema_function'
    when v.by_depend then 'begin_atomic_depend'
    when v.by_prosrc then 'prosrc_reference'
    when v.by_config then 'proconfig_search_path'
    else 'prosrc_call'
  end::text as branch,
  r.qualified_name as object,
  (
    'function '
    || case when r.in_system_schema then 'in a system schema ' else '' end
    || 'reaches quality and integrity '
    || case
      when v.by_depend then 'through pg_depend'
      when v.by_prosrc then 'through a schema named in a function body'
      when v.by_config then 'through a function search_path'
      else 'through a call named in a function body'
    end
  )::text as detail
from violation as v
join root as r on r.oid = v.seed_oid
) as v where v.branch = 'system_schema_function'
$q$, 'MT-5b.system_schema_function: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5b.prosrc_call: a plpgsql function that reads a quality table and calls, by its qualified name, another
-- plpgsql function that reads an integrity table. Neither body names both schemas, and plpgsql calls are not in
-- pg_depend, so only the call named in the body links them.
create table quality.mt_5b_score (session_id uuid, points int);
create table integrity.mt_5b_signal (session_id uuid, band text);
create function public.mt_5b_band(p_session uuid) returns text
language plpgsql
stable
set search_path = ''
as $$
begin
  return (select g.band from integrity.mt_5b_signal as g where g.session_id = p_session);
end
$$;
create function public.mt_5b_blend(p_session uuid) returns text
language plpgsql
stable
set search_path = ''
as $$
begin
  return (
    select s.points::text || public.mt_5b_band(s.session_id)
    from quality.mt_5b_score as s
    where s.session_id = p_session
  );
end
$$;
reset role;
select isnt_empty($q$
select * from (
-- MT-5b (spec specs/m0-foundations.md §8.5, rule 1): a function (any prokind), not an extension member, in any
-- non-system schema or in a system-list schema where a migration can still create objects (escape_schema below,
-- when postgres is a member of its owner), that reaches both quality and integrity by the MT-5a rule. plpgsql
-- bodies are not in pg_depend, so prosrc and proconfig are read as well. The closure (shared:graph and
-- shared:closure below, the same text in MT-5a, 5b, 5c and 5d) starts at the function and follows its pg_depend
-- rows, every call its body names (schema.name(, or an unqualified name( resolved through its search_path
-- setting), the rules of views (pg_rewrite, skipping a rule's reference to its own relation) and other functions,
-- recursively. A node reaches a schema when it lives there (a relation also reaches the schema of every member of
-- every inheritance tree it belongs to: INHERITS children and partitions alike, wherever they live), when it is a
-- type or schema ref there, or, for a function, when its prosrc outside SQL comments names it (quality. or
-- "quality"., or 'quality' as an argument of format(), quote_ident() or set_config(), case-insensitive) or its
-- proconfig search_path lists it.
-- Branches, first match wins: system_schema_function (the function lives in a system-list schema),
-- begin_atomic_depend (pg_depend alone reaches both, as for a BEGIN ATOMIC body), prosrc_reference (a prosrc match
-- is needed, no proconfig, no call), proconfig_search_path (a proconfig match is needed, no call), prosrc_call (a
-- call named in a function body is needed).
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
root as (
  select
    p.oid,
    format('%I.%I(%s)', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid))::text as qualified_name,
    n.oid in (select es.oid from escape_schema as es) as in_system_schema
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where (
      (
        n.nspname not in (
          'pg_catalog', 'information_schema', 'auth', 'storage', 'extensions', 'realtime', '_realtime',
          'graphql', 'graphql_public', 'supabase_functions', 'supabase_migrations', 'vault', 'pgsodium',
          'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
        )
        and n.nspname !~ '^pg_toast(_temp_[0-9]+)?$'
        and n.nspname !~ '^pg_temp_[0-9]+$'
      )
      or (
        n.oid in (select es.oid from escape_schema as es)
        and pg_has_role('postgres', p.proowner, 'MEMBER')
      )
    )
    and not exists (
      select 1
      from pg_depend as d
      join pg_extension as x on x.oid = d.refobjid
      where d.classid = 'pg_proc'::regclass
        and d.objid = p.oid
        and d.refclassid = 'pg_extension'::regclass
        and d.deptype = 'e'
        and x.extnamespace = p.pronamespace
    )
),
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, r.oid
  from root as r
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
violation as (
  select
    rc.seed_oid,
    count(distinct rc.nspname) filter (where rc.how = 'dep' and rc.mask & 8 = 0) = 2 as by_depend,
    count(distinct rc.nspname) filter (where rc.how in ('dep', 'src') and rc.mask & 8 = 0) = 2 as by_prosrc,
    count(distinct rc.nspname) filter (where rc.mask & 8 = 0) = 2 as by_config
  from reach as rc
  group by rc.seed_oid
  having count(distinct rc.nspname) = 2
)
select
  case
    when r.in_system_schema then 'system_schema_function'
    when v.by_depend then 'begin_atomic_depend'
    when v.by_prosrc then 'prosrc_reference'
    when v.by_config then 'proconfig_search_path'
    else 'prosrc_call'
  end::text as branch,
  r.qualified_name as object,
  (
    'function '
    || case when r.in_system_schema then 'in a system schema ' else '' end
    || 'reaches quality and integrity '
    || case
      when v.by_depend then 'through pg_depend'
      when v.by_prosrc then 'through a schema named in a function body'
      when v.by_config then 'through a function search_path'
      else 'through a call named in a function body'
    end
  )::text as detail
from violation as v
join root as r on r.oid = v.seed_oid
) as v where v.branch = 'prosrc_call'
$q$, 'MT-5b.prosrc_call: fires');
rollback to savepoint mt;
-- MT-5c
select is_empty($q$
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
$q$, 'MT-5c: clean');
savepoint mt;
-- MT-5c.direct_grantee: one role granted SELECT on a quality table and on an integrity table.
create role mt_5c_reader nologin;
create table quality.mt_5c_score (session_id uuid, points int);
create table integrity.mt_5c_signal (session_id uuid, band text);
grant select on quality.mt_5c_score to mt_5c_reader;
grant select on integrity.mt_5c_signal to mt_5c_reader;
reset role;
select isnt_empty($q$
select * from (
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
) as v where v.branch = 'direct_grantee'
$q$, 'MT-5c.direct_grantee: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5c.role_membership: two roles that each hold one schema, and a third role that is a member of both.
create role mt_5c_quality_reader nologin;
create role mt_5c_integrity_reader nologin;
create role mt_5c_worker nologin;
grant usage on schema quality to mt_5c_quality_reader;
grant usage on schema integrity to mt_5c_integrity_reader;
grant mt_5c_quality_reader, mt_5c_integrity_reader to mt_5c_worker;
reset role;
select isnt_empty($q$
select * from (
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
) as v where v.branch = 'role_membership'
$q$, 'MT-5c.role_membership: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5c.read_write_all_data: a new role made a member of pg_read_all_data. postgres holds ADMIN OPTION on
-- pg_read_all_data but not on pg_write_all_data (README day-one facts), so the fixture uses pg_read_all_data.
create role mt_5c_analyst nologin;
grant pg_read_all_data to mt_5c_analyst;
reset role;
select isnt_empty($q$
select * from (
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
) as v where v.branch = 'read_write_all_data'
$q$, 'MT-5c.read_write_all_data: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5c.definer_bridge: a role that may read a quality table and may execute an MT-7-compliant SECURITY DEFINER
-- function in private that reads an integrity table, so it reads both schemas.
create role mt_5c_bridge nologin;
create table quality.mt_5c_score (session_id uuid, points int);
create table integrity.mt_5c_signal (session_id uuid, band text);
grant select on quality.mt_5c_score to mt_5c_bridge;
create function private.mt_5c_band(p_session uuid) returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return (select g.band from integrity.mt_5c_signal as g where g.session_id = p_session);
end
$$;
revoke execute on function private.mt_5c_band(uuid) from public;
grant execute on function private.mt_5c_band(uuid) to mt_5c_bridge;
reset role;
select isnt_empty($q$
select * from (
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
) as v where v.branch = 'definer_bridge'
$q$, 'MT-5c.definer_bridge: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5c.admin_membership: a worker that inherits a quality role and holds only ADMIN OPTION (no inherit, no set) on
-- an integrity role. ADMIN lets it grant itself inherit and set later, so it holds both schemas.
create role mt_5c_quality_reader nologin;
create role mt_5c_integrity_reader nologin;
create role mt_5c_worker nologin;
grant usage on schema quality to mt_5c_quality_reader;
grant usage on schema integrity to mt_5c_integrity_reader;
grant mt_5c_quality_reader to mt_5c_worker;
grant mt_5c_integrity_reader to mt_5c_worker with admin true, inherit false, set false;
reset role;
select isnt_empty($q$
select * from (
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
) as v where v.branch = 'admin_membership'
$q$, 'MT-5c.admin_membership: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5c.owner_rights_relation: a worker that may read a quality table and a materialized view in private over an
-- integrity table. A materialized view (like a view without security_invoker=true) reads with its owner's rights,
-- so the worker reads both schemas without holding any privilege in integrity.
create role mt_5c_qworker nologin;
create table quality.mt_5c_score (session_id uuid, points int);
create table integrity.mt_5c_signal (session_id uuid, confirmed boolean);
grant usage on schema quality to mt_5c_qworker;
grant select on quality.mt_5c_score to mt_5c_qworker;
create materialized view private.mt_5c_flags as
select g.session_id, g.confirmed from integrity.mt_5c_signal as g;
grant usage on schema private to mt_5c_qworker;
grant select on private.mt_5c_flags to mt_5c_qworker;
reset role;
select isnt_empty($q$
select * from (
-- MT-5c (spec specs/m0-foundations.md §8.5, rule 1, separate worker roles, build-notes Q12): a role, other than
-- the owner and superusers, that holds privileges on objects in both quality and integrity, or a non-superuser
-- member of pg_read_all_data or pg_write_all_data that is not on the Supabase list below.
-- ACL entries counted, from the quality and integrity schemas: relations (and every relation in an inheritance tree,
-- INHERITS or partitions, that has a member there, whatever schema it lives in), columns, functions, the schemas
-- themselves, and per-schema default ACLs (pg_default_acl rows for those schemas). A null relacl, proacl or nspacl
-- is read as acldefault(), so a function with a null proacl gives EXECUTE to PUBLIC. Extension members are skipped
-- by the README rule. Also counted: EXECUTE on a SECURITY DEFINER function anywhere (outside pg_catalog and
-- information_schema) holds every schema its MT-5a closure reaches (shared:graph and shared:closure below, the same
-- text in MT-5a, 5b, 5c and 5d), because the function reads with its owner's rights. Likewise any privilege on a
-- materialized view, or on a view without the literal security_invoker=true, outside quality and integrity (outside
-- pg_catalog and information_schema too), from its relacl (acldefault when null) and column ACLs, holds every schema
-- its closure reaches. PUBLIC (grantee 0) is expanded to every role. Grantees are expanded recursively to their
-- members through pg_auth_members memberships with inherit, set or ADMIN OPTION (an ADMIN-only member can grant
-- itself inherit and set). An entry naming the object's owner (for a default ACL, defaclrole) is not counted, and
-- the owner is never expanded to its members.
-- Branches, first match wins for the two-schema rule: direct_grantee (the role is a grantee in both schemas, by
-- name or as PUBLIC), role_membership (it needs a membership with inherit or set for at least one schema),
-- admin_membership (it needs an ADMIN-only membership), definer_bridge (it needs EXECUTE on a SECURITY DEFINER
-- function for at least one schema), owner_rights_relation (it needs a privilege on a view or materialized view
-- that reads with its owner's rights). read_write_all_data (pg_read_all_data or pg_write_all_data: any direct
-- membership, then members with inherit, set or ADMIN OPTION, not expanded through postgres, the owner).
with recursive
-- Supabase roles that are members of pg_read_all_data or pg_write_all_data on the local stack
-- (day-one check, supabase/catalog-checks/README.md, 2026-10-11). Add a role only with that evidence.
supabase_data_role (rolname) as (
  values
    ('postgres'::name),
    ('supabase_etl_admin'::name),
    ('supabase_read_only_user'::name)
),
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
scope_rel as (
  select rr.nspname, c.oid, c.relkind, c.relowner, c.relacl
  from rel_reach as rr
  join pg_class as c on c.oid = rr.oid
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_class'::regclass
      and d.objid = c.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = c.relnamespace
  )
),
-- seed: the SECURITY DEFINER functions, and the materialized views and views without security_invoker=true outside
-- quality and integrity (all read with their owner's rights), walked by the shared closure.
seed (classid, oid) as (
  select 'pg_proc'::regclass::oid, p.oid
  from pg_proc as p
  join pg_namespace as n on n.oid = p.pronamespace
  where p.prosecdef
    and n.nspname not in ('pg_catalog', 'information_schema')
  union all
  select 'pg_class'::regclass::oid, c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname not in ('pg_catalog', 'information_schema', 'quality', 'integrity')
    and (
      c.relkind = 'm'
      or (c.relkind = 'v' and not ('security_invoker=true' = any(coalesce(c.reloptions, '{}'::text[]))))
    )
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
-- src: acl (an ACL entry of an object there), definer (EXECUTE on a SECURITY DEFINER function that reaches it) or
-- owner_rights (a privilege on a seeded view or materialized view that reaches it).
acl_entry (nspname, owner_oid, grantee, src) as (
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  cross join lateral aclexplode(
    coalesce(sr.relacl, acldefault(case when sr.relkind = 'S' then 's' else 'r' end::"char", sr.relowner))
  ) as a
  union
  select sr.nspname, sr.relowner, a.grantee, 'acl'::text
  from scope_rel as sr
  join pg_attribute as att on att.attrelid = sr.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
  union
  select t.nspname, p.proowner, a.grantee, 'acl'::text
  from pg_proc as p
  join target as t on t.oid = p.pronamespace
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where not exists (
    select 1
    from pg_depend as d
    join pg_extension as x on x.oid = d.refobjid
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.refclassid = 'pg_extension'::regclass
      and d.deptype = 'e'
      and x.extnamespace = p.pronamespace
  )
  union
  select t.nspname, n.nspowner, a.grantee, 'acl'::text
  from target as t
  join pg_namespace as n on n.oid = t.oid
  cross join lateral aclexplode(coalesce(n.nspacl, acldefault('n'::"char", n.nspowner))) as a
  union
  select t.nspname, da.defaclrole, a.grantee, 'acl'::text
  from pg_default_acl as da
  join target as t on t.oid = da.defaclnamespace
  cross join lateral aclexplode(da.defaclacl) as a
  union
  select rc.nspname, p.proowner, a.grantee, 'definer'::text
  from reach as rc
  join pg_proc as p on p.oid = rc.seed_oid
  cross join lateral aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as a
  where rc.seed_classid = 'pg_proc'::regclass
    and a.privilege_type = 'EXECUTE'
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  cross join lateral aclexplode(coalesce(c.relacl, acldefault('r'::"char", c.relowner))) as a
  union
  select rs.nspname, c.relowner, a.grantee, 'owner_rights'::text
  from (select distinct rc.seed_oid, rc.nspname from reach as rc where rc.seed_classid = 'pg_class'::regclass) as rs
  join pg_class as c on c.oid = rs.seed_oid
  join pg_attribute as att on att.attrelid = c.oid
  cross join lateral aclexplode(att.attacl) as a
  where att.attnum > 0
    and not att.attisdropped
    and att.attacl is not null
),
-- hop: 0 a named grantee or PUBLIC, 1 through role memberships with inherit or set, 2 through at least one
-- membership with ADMIN OPTION only (the member can grant itself inherit and set). pub: a grant to PUBLIC.
holder (role_oid, nspname, owner_oid, hop, pub, src) as (
  select e.grantee, e.nspname, e.owner_oid, 0, false, e.src
  from acl_entry as e
  where e.grantee <> 0
    and e.grantee <> e.owner_oid
  union
  select r.oid, e.nspname, e.owner_oid, 0, true, e.src
  from acl_entry as e
  cross join pg_roles as r
  where e.grantee = 0
  union
  select
    m.member,
    h.nspname,
    h.owner_oid,
    greatest(h.hop, case when m.inherit_option or m.set_option then 1 else 2 end),
    h.pub,
    h.src
  from holder as h
  join pg_auth_members as m on m.roleid = h.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and h.role_oid <> h.owner_oid
),
held as (
  select h.role_oid, h.nspname, h.hop, h.pub, h.src
  from holder as h
  join pg_roles as r on r.oid = h.role_oid
  where not r.rolsuper
    and h.role_oid <> h.owner_oid
),
both_schemas as (
  select
    hd.role_oid,
    count(distinct hd.nspname) filter (where hd.hop = 0 and hd.src = 'acl') = 2 as direct,
    count(distinct hd.nspname) filter (where hd.hop <= 1 and hd.src = 'acl') = 2 as by_membership,
    count(distinct hd.nspname) filter (where hd.src = 'acl') = 2 as by_acl,
    count(distinct hd.nspname) filter (where hd.src in ('acl', 'definer')) = 2 as by_definer,
    bool_or(hd.pub) as through_public
  from held as hd
  group by hd.role_oid
  having count(distinct hd.nspname) = 2
),
data_member (role_oid, data_role) as (
  select m.member, m.roleid
  from pg_auth_members as m
  where m.roleid in ('pg_read_all_data'::regrole, 'pg_write_all_data'::regrole)
  union
  select m.member, dm.data_role
  from data_member as dm
  join pg_auth_members as m on m.roleid = dm.role_oid
  where (m.inherit_option or m.set_option or m.admin_option)
    and dm.role_oid <> 'postgres'::regrole
)
select
  case
    when b.direct then 'direct_grantee'
    when b.by_membership then 'role_membership'
    when b.by_acl then 'admin_membership'
    when b.by_definer then 'definer_bridge'
    else 'owner_rights_relation'
  end::text as branch,
  pg_get_userbyid(b.role_oid)::text as object,
  (
    'role holds privileges in quality and integrity '
    || case
      when b.direct then 'as a grantee'
      when b.by_membership then 'through role membership'
      when b.by_acl then 'through a membership with ADMIN OPTION only'
      when b.by_definer then 'through EXECUTE on a SECURITY DEFINER function'
      else 'through a view or materialized view that reads with its owner''s rights'
    end
    || case when b.through_public then ' (counting grants to PUBLIC)' else '' end
  )::text as detail
from both_schemas as b
union all
select
  'read_write_all_data'::text,
  r.rolname::text,
  format('member of %s and not on the Supabase list', pg_get_userbyid(dm.data_role))::text
from data_member as dm
join pg_roles as r on r.oid = dm.role_oid
where not r.rolsuper
  and r.rolname not in (select s.rolname from supabase_data_role as s)
) as v where v.branch = 'owner_rights_relation'
$q$, 'MT-5c.owner_rights_relation: fires');
rollback to savepoint mt;
-- MT-5d
select is_empty($q$
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
$q$, 'MT-5d: clean');
savepoint mt;
-- MT-5d.foreign_key: a quality table with a foreign key to an integrity table.
create table integrity.mt_5d_signal (signal_id uuid primary key, band text);
create table quality.mt_5d_score (
  session_id uuid,
  points int,
  signal_id uuid references integrity.mt_5d_signal (signal_id)
);
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'foreign_key'
$q$, 'MT-5d.foreign_key: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.trigger_function: a trigger on a quality table whose plpgsql function writes to an integrity table.
create table quality.mt_5d_score (session_id uuid, points int);
create table integrity.mt_5d_signal (session_id uuid, band text);
create function public.mt_5d_copy_band() returns trigger
language plpgsql
as $$
begin
  insert into integrity.mt_5d_signal (session_id, band) values (new.session_id, 'none');
  return new;
end
$$;
create trigger mt_5d_after_score
after insert on quality.mt_5d_score
for each row execute function public.mt_5d_copy_band();
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'trigger_function'
$q$, 'MT-5d.trigger_function: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.policy_expression: a policy on a quality table whose USING expression reads an integrity table.
create table quality.mt_5d_score (session_id uuid, points int);
create table integrity.mt_5d_signal (session_id uuid, band text);
create policy mt_5d_score_select on quality.mt_5d_score
for select
to authenticated
using (
  exists (
    select 1
    from integrity.mt_5d_signal as g
    where g.session_id = mt_5d_score.session_id
  )
);
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'policy_expression'
$q$, 'MT-5d.policy_expression: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.inheritance_link: an integrity table that INHERITS from a quality table, so a scan of the quality table
-- returns integrity rows.
create table quality.mt_5d_score (session_id uuid, points int);
create table integrity.mt_5d_signal (band text) inherits (quality.mt_5d_score);
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'inheritance_link'
$q$, 'MT-5d.inheritance_link: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.table_rule: a rewrite rule on an integrity table that writes a quality table. A rule runs with the table
-- owner's rights, so it also bypasses the caller's RLS. Trace never needs table rules.
create table quality.mt_5d_score (session_id uuid, points int);
create table integrity.mt_5d_signal (session_id uuid, confirmed boolean);
create rule mt_5d_reset as on update to integrity.mt_5d_signal
where new.confirmed
do also update quality.mt_5d_score set points = 0 where session_id = new.session_id;
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'table_rule'
$q$, 'MT-5d.table_rule: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.trigger_call_chain: a trigger on an integrity table whose function calls, by an unqualified name resolved
-- through its search_path, a function that writes a quality table. The trigger function's body names neither
-- schema.
create table quality.mt_5d_score (session_id uuid, points int);
create table integrity.mt_5d_signal (session_id uuid, confirmed boolean);
create function public.mt_5d_zero(p_session uuid) returns void
language plpgsql
set search_path = ''
as $$
begin
  update quality.mt_5d_score set points = 0 where session_id = p_session;
end
$$;
create function public.mt_5d_on_signal() returns trigger
language plpgsql
set search_path = public
as $$
begin
  perform mt_5d_zero(new.session_id);
  return new;
end
$$;
create trigger mt_5d_after_signal
after update on integrity.mt_5d_signal
for each row execute function public.mt_5d_on_signal();
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'trigger_call_chain'
$q$, 'MT-5d.trigger_call_chain: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.column_default: a quality column whose default calls a plpgsql function that reads an integrity table.
create table integrity.mt_5d_signal (session_id uuid, band text);
create function public.mt_5d_flag_count() returns int
language plpgsql
stable
set search_path = ''
as $$
begin
  return (select count(*) from integrity.mt_5d_signal);
end
$$;
create table quality.mt_5d_score (session_id uuid, penalty int default public.mt_5d_flag_count());
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'column_default'
$q$, 'MT-5d.column_default: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.check_constraint: a CHECK constraint on a quality table that calls a plpgsql function reading an integrity
-- table.
create table integrity.mt_5d_signal (session_id uuid, band text);
create function public.mt_5d_unflagged(p_session uuid) returns boolean
language plpgsql
stable
set search_path = ''
as $$
begin
  return not exists (select 1 from integrity.mt_5d_signal as g where g.session_id = p_session);
end
$$;
create table quality.mt_5d_score (
  session_id uuid,
  points int,
  constraint mt_5d_score_unflagged check (public.mt_5d_unflagged(session_id))
);
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'check_constraint'
$q$, 'MT-5d.check_constraint: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.index_expression: an expression index on a quality table over a function (marked immutable, which
-- PostgreSQL does not verify) that reads an integrity table.
create table integrity.mt_5d_signal (session_id uuid, band text);
create function public.mt_5d_band_of(p_session uuid) returns text
language plpgsql
immutable
set search_path = ''
as $$
begin
  return (select g.band from integrity.mt_5d_signal as g where g.session_id = p_session);
end
$$;
create table quality.mt_5d_score (session_id uuid, points int);
create index mt_5d_score_band on quality.mt_5d_score (public.mt_5d_band_of(session_id));
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'index_expression'
$q$, 'MT-5d.index_expression: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.column_domain: a quality column typed by a public domain whose CHECK calls a plpgsql function that reads an
-- integrity table, so every write to the column reads integrity.
create table integrity.mt_5d_signal (session_id uuid, band text);
create function public.mt_5d_points_ok(p_points int) returns boolean
language plpgsql
stable
set search_path = ''
as $$
begin
  return p_points >= (select count(*) from integrity.mt_5d_signal);
end
$$;
create domain public.mt_5d_points as int check (public.mt_5d_points_ok(value));
create table quality.mt_5d_score (session_id uuid, points public.mt_5d_points);
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'column_domain'
$q$, 'MT-5d.column_domain: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.outside_host_both: a policy on a public table whose USING reads a quality table and an integrity table.
-- A plain table outside the two schemas may hold foreign keys into both (founder decision 2026-10-11), but code on
-- it must not combine them.
create table quality.mt_5d_score (session_id uuid, points int);
create table integrity.mt_5d_signal (session_id uuid, band text);
create table public.mt_5d_report (org_id uuid not null, session_id uuid);
create policy mt_5d_report_select on public.mt_5d_report
for select
to authenticated
using (
  exists (
    select 1
    from quality.mt_5d_score as s
    join integrity.mt_5d_signal as g on g.session_id = s.session_id
    where s.session_id = mt_5d_report.session_id
  )
);
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'outside_host_both'
$q$, 'MT-5d.outside_host_both: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-5d.system_table_trigger: a trigger on auth.users, a Supabase table outside the catalog-check scope (postgres
-- holds TRIGGER on it), whose WHEN clause reads an integrity table and whose function zeroes a quality score: an
-- integrity condition edits a quality score. Neither function reaches both schemas on its own.
create table quality.mt_5d_score (org_id uuid not null, user_id uuid, points int);
create table integrity.mt_5d_signal (org_id uuid not null, user_id uuid, confirmed boolean);
alter table quality.mt_5d_score enable row level security;
alter table integrity.mt_5d_signal enable row level security;
create function private.mt_5d_is_flagged(p_user uuid) returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (select 1 from integrity.mt_5d_signal as g where g.user_id = p_user and g.confirmed)
$$;
create function private.mt_5d_zero() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update quality.mt_5d_score set points = 0 where user_id = new.id;
  return new;
end
$$;
create trigger mt_5d_user_flagged
after update on auth.users
for each row
when (private.mt_5d_is_flagged(new.id))
execute function private.mt_5d_zero();
reset role;
select isnt_empty($q$
select * from (
-- MT-5d (spec specs/m0-foundations.md §8.5, rule 1): a link between quality and integrity that is not a view or
-- a function. A relation reaches a schema when it lives there, and also reaches the schema of every member of every
-- inheritance tree it belongs to (INHERITS children and partitions alike, wherever they live). Branches:
--   foreign_key: a foreign key (pg_constraint contype f) whose table reaches one of the two schemas and whose
--     referenced table reaches the other.
--   trigger_function: a trigger (not internal, so not the foreign-key triggers) on a table that reaches one schema,
--     whose pg_depend rows (skipping the reference to its own table) reach the other by the MT-5a rule without a
--     call named in a function body.
--   policy_expression: a policy (pg_depend classid pg_policy, skipping the reference to its own table) on a table
--     that reaches one schema, whose expressions reach the other by the MT-5a rule.
--   inheritance_link: an inheritance tree (INHERITS or partitions) with members in both schemas, reported at its
--     root, so a scan of one schema's table returns the other schema's rows.
--   table_rule: any rewrite rule other than a view's _RETURN rule on an in-scope relation (scope_rel below). A rule
--     runs with the table owner's rights, so it can link the two schemas and bypass RLS. Trace never needs one.
--   trigger_call_chain: as trigger_function, but the other schema is reached only through a call named in a
--     function body (schema.name(, or an unqualified name( resolved through the caller's search_path setting).
--   column_default: a column default or generated column (pg_attrdef) on a table that reaches one schema, whose
--     expression reaches the other.
--   check_constraint: a CHECK constraint (pg_constraint contype c) on such a table whose expression reaches the
--     other.
--   index_expression: an index with expressions or a predicate on such a table that reaches the other.
--   column_domain: a column of such a table typed by a domain (or an array of one) whose default or CHECK
--     constraints reach the other.
--   outside_host_both: any of those hosts (trigger, policy, column default, CHECK constraint, index, domain column)
--     on an in-scope relation that reaches neither schema (public, private, a system-list schema or an inheritance
--     descendant elsewhere), whose code reaches both. Founder decision 2026-10-11: such a table (the plan's reports
--     table) may hold foreign keys into both schemas and show both results side by side (rule 5), so its foreign
--     keys are not flagged, but code on it must not combine them (rule 1).
--   system_table_trigger: a trigger on a relation outside scope_rel (such as auth.users or storage.objects, where
--     postgres holds TRIGGER), whose code (its WHEN clause and its function) reaches both. Triggers are the one host
--     a migration can attach to a table it does not own, so trigger hosts are taken from every relation, not only
--     scope_rel.
-- The MT-5a rule is the closure in shared:graph and shared:closure below (the same text in MT-5a, 5b, 5c and 5d).
-- Extension members are not skipped here: an extension installed in quality or integrity is already an MT-9
-- violation.
with recursive
-- shared:graph begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
target as (
  select n.oid, n.nspname::text as nspname
  from pg_namespace as n
  where n.nspname in ('quality', 'integrity')
),
-- family: every inheritance tree (INHERITS children and partitions are both pg_inherits rows) as (root, member)
-- pairs, the root included. A relation under several parents is a member of each parent's tree.
family (root_oid, member_oid) as (
  select i.inhparent, i.inhparent
  from pg_inherits as i
  where not exists (select 1 from pg_inherits as up where up.inhrelid = i.inhparent)
  union
  select f.root_oid, i.inhrelid
  from family as f
  join pg_inherits as i on i.inhparent = f.member_oid
),
-- rel_reach: a relation reaches a target schema when it lives there, or when a member of an inheritance tree it
-- belongs to lives there, whatever schema the relation itself is in.
rel_reach as (
  select c.oid, t.nspname
  from pg_class as c
  join target as t on t.oid = c.relnamespace
  union
  select f.member_oid, t.nspname
  from family as f
  join family as g on g.root_oid = f.root_oid
  join pg_class as gc on gc.oid = g.member_oid
  join target as t on t.oid = gc.relnamespace
),
-- caller: a function in any language but c and internal, with its body without SQL comments (src, and lsrc
-- lowercased) and the schemas its search_path setting lists (public and extensions, the database default, when it
-- has none). A single pass reads the body left to right: a string literal ('...', '' inside) or a quoted identifier
-- ("...", "" inside) is kept, so a -- or /* inside one is not a comment, and each -- comment (to the end of its
-- line) or /* */ comment becomes a space. Each kept literal or identifier gets a space after it, which no pattern
-- below depends on.
caller as materialized (
  select b.oid, b.src, lower(b.src) as lsrc, b.path
  from (
    select
      f.oid,
      regexp_replace(
        f.prosrc,
        '(''(?:[^'']|'''')*''|"(?:[^"]|"")*")|--[^\n]*|/\*(?:[^*]|\*+[^*/])*\*+/',
        '\1 ',
        'g'
      ) as src,
      sp.path
    from pg_proc as f
    join pg_language as l on l.oid = f.prolang
    cross join lateral (
      select coalesce(array_agg(btrim(s.part, ' "')), array['public', 'extensions']) as path
      from unnest(f.proconfig) as cfg(setting)
      cross join lateral regexp_split_to_table(substr(cfg.setting, 13), ',') as s(part)
      where left(cfg.setting, 12) = 'search_path='
    ) as sp
    where l.lanname not in ('c', 'internal')
  ) as b
),
-- callee: a function outside pg_catalog and information_schema, its schema and name escaped for a regex.
callee as materialized (
  select
    g.oid,
    lower(g.proname) as lname,
    n.nspname::text as nspname,
    regexp_replace(n.nspname, '([^[:alnum:]_])', '\\\1', 'g') as nsp,
    regexp_replace(g.proname, '([^[:alnum:]_])', '\\\1', 'g') as fn
  from pg_proc as g
  join pg_namespace as n on n.oid = g.pronamespace
  where n.nspname not in ('pg_catalog', 'information_schema')
),
-- code_edge: one step of the walk, from (classid, objid) to (refclassid, refobjid). bit tags the kind of step:
-- 1 into an operator (node_edge), 4 out of a domain or array type, 8 a call named in a function body, 0 any other.
-- A cast in an expression is recorded in pg_depend as its cast function, so casts need no step of their own.
code_edge (classid, objid, refclassid, refobjid, bit) as (
  -- the rules of a relation (a view body or a table rule), skipping a rule's reference to its own relation
  select 'pg_class'::regclass::oid, r.ev_class, d.refclassid, d.refobjid, 0
  from pg_rewrite as r
  join pg_depend as d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = r.ev_class)
  union
  -- the pg_depend rows of a function (all of a BEGIN ATOMIC body, only the signature of any other) and of an
  -- operator (its oprcode)
  select d.classid, d.objid, d.refclassid, d.refobjid, 0
  from pg_depend as d
  where d.classid in ('pg_proc'::regclass, 'pg_operator'::regclass)
  union
  -- a CHECK constraint of a table or a domain, skipping its reference to its own table
  select 'pg_constraint'::regclass::oid, con.oid, d.refclassid, d.refobjid, 0
  from pg_constraint as con
  join pg_depend as d on d.classid = 'pg_constraint'::regclass and d.objid = con.oid
  where con.contype = 'c'
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = con.conrelid)
  union
  -- a column default or generated column, skipping its reference to its own table
  select 'pg_attrdef'::regclass::oid, ad.oid, d.refclassid, d.refobjid, 0
  from pg_attrdef as ad
  join pg_depend as d on d.classid = 'pg_attrdef'::regclass and d.objid = ad.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = ad.adrelid)
  union
  -- an index with expressions or a predicate, skipping its reference to its own table
  select 'pg_class'::regclass::oid, ix.indexrelid, d.refclassid, d.refobjid, 0
  from pg_index as ix
  join pg_depend as d on d.classid = 'pg_class'::regclass and d.objid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and not (d.refclassid = 'pg_class'::regclass and d.refobjid = ix.indrelid)
  union
  -- a domain: its pg_depend rows (such as a default expression) and its CHECK constraints
  select 'pg_type'::regclass::oid, ty.oid, d.refclassid, d.refobjid, 4
  from pg_type as ty
  join pg_depend as d on d.classid = 'pg_type'::regclass and d.objid = ty.oid
  where ty.typtype = 'd'
  union
  select 'pg_type'::regclass::oid, con.contypid, 'pg_constraint'::regclass::oid, con.oid, 4
  from pg_constraint as con
  where con.contypid <> 0
    and con.contype = 'c'
  union
  -- an array type: its element type, so an array of a domain reaches the domain
  select 'pg_type'::regclass::oid, ty.oid, 'pg_type'::regclass::oid, ty.typelem, 4
  from pg_type as ty
  where ty.typelem <> 0
    and ty.typsubscript = 'array_subscript_handler'::regproc
  union
  -- a trigger, skipping its reference to its own table
  select 'pg_trigger'::regclass::oid, tg.oid, d.refclassid, d.refobjid, 0
  from pg_trigger as tg
  join pg_depend as d on d.classid = 'pg_trigger'::regclass and d.objid = tg.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = tg.tgrelid)
  union
  -- a policy, skipping its reference to its own table
  select 'pg_policy'::regclass::oid, pol.oid, d.refclassid, d.refobjid, 0
  from pg_policy as pol
  join pg_depend as d on d.classid = 'pg_policy'::regclass and d.objid = pol.oid
  where not (d.refclassid = 'pg_class'::regclass and d.refobjid = pol.polrelid)
  union
  -- a call named in a caller's body: schema.name( for any schema, or an unqualified name( when the callee's schema
  -- is on the caller's search_path. Every overload of the name counts.
  select 'pg_proc'::regclass::oid, f.oid, 'pg_proc'::regclass::oid, g.oid, 8
  from caller as f
  join callee as g on position(g.lname in f.lsrc) > 0
  where f.src ~* (
      '(^|[^[:alnum:]_$."])"?' || g.nsp || '"?[[:space:]]*\.[[:space:]]*"?' || g.fn || '"?[[:space:]]*\('
    )
    or (
      g.nspname = any(f.path)
      and f.src ~* ('(^|[^[:alnum:]_$."])"?' || g.fn || '"?[[:space:]]*\(')
    )
),
-- materialized: computed once, not once per step of the recursive walk
node_edge as materialized (
  select
    e.classid,
    e.objid,
    e.refclassid,
    e.refobjid,
    e.bit | case when e.refclassid = 'pg_operator'::regclass then 1 else 0 end as bit
  from code_edge as e
  where e.refclassid in (
    'pg_class'::regclass, 'pg_proc'::regclass, 'pg_type'::regclass, 'pg_namespace'::regclass,
    'pg_operator'::regclass, 'pg_constraint'::regclass
  )
),
-- shared:graph end
-- shared:escape begin (the same text in MT-5a, MT-5b, MT-5d, MT-10 and MT-11)
-- escape_schema: system-list schemas where a migration can still create objects (spec §8.5 revision 12): postgres
-- is a member (INHERIT, SET or ADMIN) of the schema owner or of a role with CREATE on it. An ADMIN-only member can
-- grant itself SET. Locally: extensions, _realtime, supabase_functions and supabase_migrations, plus any listed
-- schema that a migration creates (cron, net and so on).
escape_schema as (
  select n.oid
  from pg_namespace as n
  where n.nspname in (
      'auth', 'storage', 'extensions', 'realtime', '_realtime', 'graphql', 'graphql_public', 'supabase_functions',
      'supabase_migrations', 'vault', 'pgsodium', 'pgsodium_masks', 'net', 'cron', 'pgbouncer', '_analytics'
    )
    and (
      pg_has_role('postgres', n.nspowner, 'MEMBER')
      or exists (
        select 1
        from pg_roles as r
        where pg_has_role('postgres', r.oid, 'MEMBER')
          and has_schema_privilege(r.oid, n.oid, 'CREATE')
      )
    )
),
-- shared:escape end
-- scope_rel: the in-scope relations. Every relation in public, private, quality and integrity, every relation in an
-- escape_schema whose owner postgres is a member of, every pg_inherits descendant of those, wherever it lives, and
-- every relation that reaches quality or integrity (rel_reach).
scope_rel (oid) as (
  select c.oid
  from pg_class as c
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname in ('public', 'private', 'quality', 'integrity')
  union
  select c.oid
  from pg_class as c
  where c.relnamespace in (select es.oid from escape_schema as es)
    and pg_has_role('postgres', c.relowner, 'MEMBER')
  union
  select rr.oid
  from rel_reach as rr
  union
  select i.inhrelid
  from scope_rel as s
  join pg_inherits as i on i.inhparent = s.oid
),
foreign_key as (
  select
    format('%I on %I.%I', con.conname, n.nspname, c.relname)::text as object,
    format('foreign key from %s to %s', src.nspname, ref.nspname)::text as detail
  from pg_constraint as con
  join pg_class as c on c.oid = con.conrelid
  join pg_namespace as n on n.oid = c.relnamespace
  join rel_reach as src on src.oid = con.conrelid
  join rel_reach as ref on ref.oid = con.confrelid
  where con.contype = 'f'
    and src.nspname <> ref.nspname
),
-- host: code attached to an in-scope relation, walked from the host itself (its edges are in code_edge). kind
-- names the branch. Triggers are taken on every relation (system_table_trigger): TRIGGER is a privilege, so a
-- migration can attach one to a table it does not own.
host (classid, oid, relid, name, kind) as (
  select 'pg_trigger'::regclass::oid, tg.oid, tg.tgrelid, format('%I', tg.tgname), 'trigger'::text
  from pg_trigger as tg
  where not tg.tgisinternal
  union all
  select 'pg_policy'::regclass::oid, pol.oid, pol.polrelid, format('%I', pol.polname), 'policy'::text
  from pg_policy as pol
  where pol.polrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_attrdef'::regclass::oid, ad.oid, ad.adrelid, format('default of %I', a.attname), 'default'::text
  from pg_attrdef as ad
  join pg_attribute as a on a.attrelid = ad.adrelid and a.attnum = ad.adnum
  where ad.adrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_constraint'::regclass::oid, con.oid, con.conrelid, format('%I', con.conname), 'check'::text
  from pg_constraint as con
  where con.contype = 'c'
    and con.conrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_class'::regclass::oid, ix.indexrelid, ix.indrelid, format('index %I', ic.relname), 'index'::text
  from pg_index as ix
  join pg_class as ic on ic.oid = ix.indexrelid
  where (ix.indexprs is not null or ix.indpred is not null)
    and ix.indrelid in (select s.oid from scope_rel as s)
  union all
  select 'pg_type'::regclass::oid, a.atttypid, a.attrelid, format('column %I', a.attname), 'domain'::text
  from pg_attribute as a
  join pg_type as ty on ty.oid = a.atttypid
  left join pg_type as el on el.oid = ty.typelem
  where a.attnum > 0
    and not a.attisdropped
    and (ty.typtype = 'd' or el.typtype = 'd')
    and a.attrelid in (select s.oid from scope_rel as s)
),
seed (classid, oid) as (
  select distinct h.classid, h.oid
  from host as h
),
-- shared:closure begin (the same text in MT-5a, MT-5b, MT-5c and MT-5d)
-- closure: the walk from each seed (defined by the check). lvl: 0 the seed, 1 a direct reference of the seed, 2
-- reached through other relations or types only, 3 reached through a function. mask ORs the bits of the steps
-- taken. UNION keeps the walk finite on cycles.
closure (seed_classid, seed_oid, classid, objid, lvl, mask) as (
  select s.classid, s.oid, s.classid, s.oid, 0, 0
  from seed as s
  union
  select
    cl.seed_classid,
    cl.seed_oid,
    e.refclassid,
    e.refobjid,
    case
      when cl.lvl = 3 or e.refclassid = 'pg_proc'::regclass then 3
      when cl.lvl = 0 then 1
      else 2
    end,
    cl.mask | e.bit
  from closure as cl
  join node_edge as e on e.classid = cl.classid and e.objid = cl.objid
),
-- reach: a node of the walk reaches a target schema. how: dep when the node lives there (a relation through its
-- inheritance trees too) or is a type, schema or function there, src when a function body without comments
-- (caller.src) names the schema (quality. or "quality"., or 'quality' as an argument of format(), quote_ident() or
-- set_config(): after the call's open parenthesis in the same statement, case-insensitive), cfg when a function's
-- search_path setting lists it.
reach (seed_classid, seed_oid, nspname, lvl, mask, how) as (
  select cl.seed_classid, cl.seed_oid, rr.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join rel_reach as rr on rr.oid = cl.objid
  where cl.classid = 'pg_class'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_type as ty on ty.oid = cl.objid
  join target as t on t.oid = ty.typnamespace
  where cl.classid = 'pg_type'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join target as t on t.oid = cl.objid
  where cl.classid = 'pg_namespace'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'dep'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  join target as t on t.oid = p.pronamespace
  where cl.classid = 'pg_proc'::regclass
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'src'::text
  from closure as cl
  join caller as f on f.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and position(t.nspname in f.lsrc) > 0
    and (
      f.src ~* ('(^|[^[:alnum:]_$])("' || t.nspname || '"|' || t.nspname || ')[[:space:]]*\.')
      -- format(, quote_ident( or set_config( then string literals or anything but a quote or a semicolon (\x3b, the
      -- end of the statement), then the schema as a literal
      or f.src ~* (
        '(^|[^[:alnum:]_$])(?:format|quote_ident|set_config)[[:space:]]*\('
        || '(?:[^''\x3b]|''(?:[^'']|'''')*'')*''' || t.nspname || ''''
      )
    )
  union all
  select cl.seed_classid, cl.seed_oid, t.nspname, cl.lvl, cl.mask, 'cfg'::text
  from closure as cl
  join pg_proc as p on p.oid = cl.objid
  cross join target as t
  where cl.classid = 'pg_proc'::regclass
    and exists (
      select 1
      from unnest(p.proconfig) as cfg(setting)
      where cfg.setting ~* ('^search_path=(.*,)?[[:space:]]*"?' || t.nspname || '"?[[:space:]]*(,|$)')
    )
),
-- shared:closure end
crossing as (
  select
    h.kind,
    h.relid,
    h.name,
    hr.nspname as host_nspname,
    rc.nspname as other_nspname,
    bool_or(rc.mask & 8 = 0) as without_call
  from host as h
  join rel_reach as hr on hr.oid = h.relid
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where rc.nspname <> hr.nspname
  group by h.kind, h.classid, h.oid, h.relid, h.name, hr.nspname, rc.nspname
),
-- outside: a host on a relation that reaches neither schema, whose code reaches both (system_table_trigger when the
-- host is a trigger on a relation outside scope_rel, outside_host_both otherwise).
outside as (
  select h.kind, h.relid, h.name
  from host as h
  join reach as rc on rc.seed_classid = h.classid and rc.seed_oid = h.oid
  where h.relid not in (select rr.oid from rel_reach as rr)
  group by h.kind, h.classid, h.oid, h.relid, h.name
  having count(distinct rc.nspname) = 2
)
select
  'foreign_key'::text as branch,
  fk.object,
  fk.detail
from foreign_key as fk
union all
select
  case x.kind
    when 'trigger' then case when x.without_call then 'trigger_function' else 'trigger_call_chain' end
    when 'policy' then 'policy_expression'
    when 'default' then 'column_default'
    when 'check' then 'check_constraint'
    when 'index' then 'index_expression'
    else 'column_domain'
  end::text,
  format('%s on %I.%I', x.name, n.nspname, c.relname)::text,
  format(
    '%s on a table of schema %s reaches %s%s',
    case x.kind
      when 'default' then 'column default'
      when 'check' then 'CHECK constraint'
      when 'domain' then 'column domain'
      else x.kind
    end,
    x.host_nspname,
    x.other_nspname,
    case when x.without_call then '' else ' through a call named in a function body' end
  )::text
from crossing as x
join pg_class as c on c.oid = x.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  case
    when o.relid in (select s.oid from scope_rel as s) then 'outside_host_both'
    else 'system_table_trigger'
  end::text,
  format('%s on %I.%I', o.name, n.nspname, c.relname)::text,
  case
    when o.relid in (select s.oid from scope_rel as s) then format(
      '%s on a table outside quality and integrity reaches both',
      case o.kind
        when 'default' then 'column default'
        when 'check' then 'CHECK constraint'
        when 'domain' then 'column domain'
        else o.kind
      end
    )
    else 'trigger on a relation outside the catalog-check scope reaches quality and integrity'
  end::text
from outside as o
join pg_class as c on c.oid = o.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'inheritance_link'::text,
  format('%I.%I', n.nspname, c.relname)::text,
  'inheritance tree has members in quality and integrity'::text
from family as f
join pg_class as mc on mc.oid = f.member_oid
join target as t on t.oid = mc.relnamespace
join pg_class as c on c.oid = f.root_oid
join pg_namespace as n on n.oid = c.relnamespace
group by f.root_oid, n.nspname, c.relname
having count(distinct t.nspname) = 2
union all
select
  'table_rule'::text,
  format('%I on %I.%I', r.rulename, n.nspname, c.relname)::text,
  'rewrite rule on an in-scope relation (Trace never needs table rules)'::text
from pg_rewrite as r
join pg_class as c on c.oid = r.ev_class
join pg_namespace as n on n.oid = c.relnamespace
where r.rulename <> '_RETURN'
  and r.ev_class in (select s.oid from scope_rel as s)
) as v where v.branch = 'system_table_trigger'
$q$, 'MT-5d.system_table_trigger: fires');
rollback to savepoint mt;
-- MT-6
select is_empty($q$
-- MT-6 (spec specs/m0-foundations.md §8.5, rule 2): an enum with a label where lower(enumlabel) like '%reject%', if
-- the enum type is in schema integrity, or is used by a column of a relation (table, partitioned table, view,
-- materialized view or foreign table) in integrity. Column use is resolved recursively, through any mix of: an
-- array type (typelem of a true array), a domain (typbasetype), a composite type (the types of its attributes,
-- through typrelid), a range (pg_range.rngsubtype) or a multirange (its range, pg_range.rngmultitypid). A use that
-- passes through any domain is domain_column, else through an array array_column, else through a composite type
-- composite_column, else through a range or multirange range_column, else direct_column. The depth guard only stops
-- runaway recursion. unused_integrity_enum covers an integrity enum that no integrity column uses. Extension members
-- in their extension's own namespace are skipped.
with recursive integrity_column (relid, attname, typid, via_domain, via_array, via_composite, via_range, depth) as (
  select a.attrelid, a.attname, a.atttypid, false, false, false, false, 0
  from pg_attribute as a
  join pg_class as c on c.oid = a.attrelid
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname = 'integrity'
    and c.relkind in ('r', 'p', 'v', 'm', 'f')
    and a.attnum > 0
    and not a.attisdropped
  union all
  select
    ic.relid,
    ic.attname,
    st.typid,
    ic.via_domain or st.step = 'domain',
    ic.via_array or st.step = 'array',
    ic.via_composite or st.step = 'composite',
    ic.via_range or st.step = 'range',
    ic.depth + 1
  from integrity_column as ic
  cross join lateral (
    select 'domain'::text as step, t.typbasetype as typid
    from pg_type as t
    where t.oid = ic.typid
      and t.typtype = 'd'
    union all
    select 'array'::text, t.typelem
    from pg_type as t
    where t.oid = ic.typid
      and t.typelem <> 0
      and t.typsubscript = 'array_subscript_handler'::regproc
    union all
    select 'composite'::text, a.atttypid
    from pg_type as t
    join pg_attribute as a on a.attrelid = t.typrelid
    where t.oid = ic.typid
      and t.typtype = 'c'
      and a.attnum > 0
      and not a.attisdropped
    union all
    select 'range'::text, r.rngsubtype
    from pg_range as r
    where r.rngtypid = ic.typid
    union all
    select 'range'::text, r.rngtypid
    from pg_range as r
    where r.rngmultitypid = ic.typid
  ) as st
  where ic.depth < 32
),
reject_enum as (
  select t.oid, n.nspname, t.typname
  from pg_type as t
  join pg_namespace as n on n.oid = t.typnamespace
  where t.typtype = 'e'
    and exists (
      select 1
      from pg_enum as e
      where e.enumtypid = t.oid
        and lower(e.enumlabel) like '%reject%'
    )
    and not exists (
      select 1
      from pg_depend as d
      join pg_extension as x on x.oid = d.refobjid
      where d.classid = 'pg_type'::regclass
        and d.objid = t.oid
        and d.refclassid = 'pg_extension'::regclass
        and d.deptype = 'e'
        and x.extnamespace = t.typnamespace
    )
),
reject_use as (
  select
    ic.relid,
    ic.attname,
    ic.via_domain,
    ic.via_array,
    ic.via_composite,
    ic.via_range,
    re.oid as enum_oid,
    re.nspname,
    re.typname
  from integrity_column as ic
  join reject_enum as re on re.oid = ic.typid
)
select
  case
    when ru.via_domain then 'domain_column'
    when ru.via_array then 'array_column'
    when ru.via_composite then 'composite_column'
    when ru.via_range then 'range_column'
    else 'direct_column'
  end::text as branch,
  format('%I.%I.%I', n.nspname, c.relname, ru.attname)::text as object,
  format('column uses enum %I.%I, which has a reject label', ru.nspname, ru.typname)::text as detail
from reject_use as ru
join pg_class as c on c.oid = ru.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'unused_integrity_enum'::text,
  format('%I.%I', re.nspname, re.typname)::text,
  'enum in schema integrity has a reject label'::text
from reject_enum as re
where re.nspname = 'integrity'
  and not exists (
    select 1
    from reject_use as ru
    where ru.enum_oid = re.oid
  )
$q$, 'MT-6: clean');
savepoint mt;
-- MT-6.unused_integrity_enum: an enum in schema integrity with the label auto_reject, used by no column.
create type integrity.mt_6_outcome as enum ('pass', 'auto_reject');
reset role;
select isnt_empty($q$
select * from (
-- MT-6 (spec specs/m0-foundations.md §8.5, rule 2): an enum with a label where lower(enumlabel) like '%reject%', if
-- the enum type is in schema integrity, or is used by a column of a relation (table, partitioned table, view,
-- materialized view or foreign table) in integrity. Column use is resolved recursively, through any mix of: an
-- array type (typelem of a true array), a domain (typbasetype), a composite type (the types of its attributes,
-- through typrelid), a range (pg_range.rngsubtype) or a multirange (its range, pg_range.rngmultitypid). A use that
-- passes through any domain is domain_column, else through an array array_column, else through a composite type
-- composite_column, else through a range or multirange range_column, else direct_column. The depth guard only stops
-- runaway recursion. unused_integrity_enum covers an integrity enum that no integrity column uses. Extension members
-- in their extension's own namespace are skipped.
with recursive integrity_column (relid, attname, typid, via_domain, via_array, via_composite, via_range, depth) as (
  select a.attrelid, a.attname, a.atttypid, false, false, false, false, 0
  from pg_attribute as a
  join pg_class as c on c.oid = a.attrelid
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname = 'integrity'
    and c.relkind in ('r', 'p', 'v', 'm', 'f')
    and a.attnum > 0
    and not a.attisdropped
  union all
  select
    ic.relid,
    ic.attname,
    st.typid,
    ic.via_domain or st.step = 'domain',
    ic.via_array or st.step = 'array',
    ic.via_composite or st.step = 'composite',
    ic.via_range or st.step = 'range',
    ic.depth + 1
  from integrity_column as ic
  cross join lateral (
    select 'domain'::text as step, t.typbasetype as typid
    from pg_type as t
    where t.oid = ic.typid
      and t.typtype = 'd'
    union all
    select 'array'::text, t.typelem
    from pg_type as t
    where t.oid = ic.typid
      and t.typelem <> 0
      and t.typsubscript = 'array_subscript_handler'::regproc
    union all
    select 'composite'::text, a.atttypid
    from pg_type as t
    join pg_attribute as a on a.attrelid = t.typrelid
    where t.oid = ic.typid
      and t.typtype = 'c'
      and a.attnum > 0
      and not a.attisdropped
    union all
    select 'range'::text, r.rngsubtype
    from pg_range as r
    where r.rngtypid = ic.typid
    union all
    select 'range'::text, r.rngtypid
    from pg_range as r
    where r.rngmultitypid = ic.typid
  ) as st
  where ic.depth < 32
),
reject_enum as (
  select t.oid, n.nspname, t.typname
  from pg_type as t
  join pg_namespace as n on n.oid = t.typnamespace
  where t.typtype = 'e'
    and exists (
      select 1
      from pg_enum as e
      where e.enumtypid = t.oid
        and lower(e.enumlabel) like '%reject%'
    )
    and not exists (
      select 1
      from pg_depend as d
      join pg_extension as x on x.oid = d.refobjid
      where d.classid = 'pg_type'::regclass
        and d.objid = t.oid
        and d.refclassid = 'pg_extension'::regclass
        and d.deptype = 'e'
        and x.extnamespace = t.typnamespace
    )
),
reject_use as (
  select
    ic.relid,
    ic.attname,
    ic.via_domain,
    ic.via_array,
    ic.via_composite,
    ic.via_range,
    re.oid as enum_oid,
    re.nspname,
    re.typname
  from integrity_column as ic
  join reject_enum as re on re.oid = ic.typid
)
select
  case
    when ru.via_domain then 'domain_column'
    when ru.via_array then 'array_column'
    when ru.via_composite then 'composite_column'
    when ru.via_range then 'range_column'
    else 'direct_column'
  end::text as branch,
  format('%I.%I.%I', n.nspname, c.relname, ru.attname)::text as object,
  format('column uses enum %I.%I, which has a reject label', ru.nspname, ru.typname)::text as detail
from reject_use as ru
join pg_class as c on c.oid = ru.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'unused_integrity_enum'::text,
  format('%I.%I', re.nspname, re.typname)::text,
  'enum in schema integrity has a reject label'::text
from reject_enum as re
where re.nspname = 'integrity'
  and not exists (
    select 1
    from reject_use as ru
    where ru.enum_oid = re.oid
  )
) as v where v.branch = 'unused_integrity_enum'
$q$, 'MT-6.unused_integrity_enum: fires');
rollback to savepoint mt;
savepoint mt;
-- MT-6.direct_column: an enum from schema public with a reject label, used directly by a column of an integrity table.
create type public.mt_6_status as enum ('kept', 'rejected');
create table integrity.mt_6_review (org_id uuid not null, status public.mt_6_status);
reset role;
select isnt_empty($q$
select * from (
-- MT-6 (spec specs/m0-foundations.md §8.5, rule 2): an enum with a label where lower(enumlabel) like '%reject%', if
-- the enum type is in schema integrity, or is used by a column of a relation (table, partitioned table, view,
-- materialized view or foreign table) in integrity. Column use is resolved recursively, through any mix of: an
-- array type (typelem of a true array), a domain (typbasetype), a composite type (the types of its attributes,
-- through typrelid), a range (pg_range.rngsubtype) or a multirange (its range, pg_range.rngmultitypid). A use that
-- passes through any domain is domain_column, else through an array array_column, else through a composite type
-- composite_column, else through a range or multirange range_column, else direct_column. The depth guard only stops
-- runaway recursion. unused_integrity_enum covers an integrity enum that no integrity column uses. Extension members
-- in their extension's own namespace are skipped.
with recursive integrity_column (relid, attname, typid, via_domain, via_array, via_composite, via_range, depth) as (
  select a.attrelid, a.attname, a.atttypid, false, false, false, false, 0
  from pg_attribute as a
  join pg_class as c on c.oid = a.attrelid
  join pg_namespace as n on n.oid = c.relnamespace
  where n.nspname = 'integrity'
    and c.relkind in ('r', 'p', 'v', 'm', 'f')
    and a.attnum > 0
    and not a.attisdropped
  union all
  select
    ic.relid,
    ic.attname,
    st.typid,
    ic.via_domain or st.step = 'domain',
    ic.via_array or st.step = 'array',
    ic.via_composite or st.step = 'composite',
    ic.via_range or st.step = 'range',
    ic.depth + 1
  from integrity_column as ic
  cross join lateral (
    select 'domain'::text as step, t.typbasetype as typid
    from pg_type as t
    where t.oid = ic.typid
      and t.typtype = 'd'
    union all
    select 'array'::text, t.typelem
    from pg_type as t
    where t.oid = ic.typid
      and t.typelem <> 0
      and t.typsubscript = 'array_subscript_handler'::regproc
    union all
    select 'composite'::text, a.atttypid
    from pg_type as t
    join pg_attribute as a on a.attrelid = t.typrelid
    where t.oid = ic.typid
      and t.typtype = 'c'
      and a.attnum > 0
      and not a.attisdropped
    union all
    select 'range'::text, r.rngsubtype
    from pg_range as r
    where r.rngtypid = ic.typid
    union all
    select 'range'::text, r.rngtypid
    from pg_range as r
    where r.rngmultitypid = ic.typid
  ) as st
  where ic.depth < 32
),
reject_enum as (
  select t.oid, n.nspname, t.typname
  from pg_type as t
  join pg_namespace as n on n.oid = t.typnamespace
  where t.typtype = 'e'
    and exists (
      select 1
      from pg_enum as e
      where e.enumtypid = t.oid
        and lower(e.enumlabel) like '%reject%'
    )
    and not exists (
      select 1
      from pg_depend as d
      join pg_extension as x on x.oid = d.refobjid
      where d.classid = 'pg_type'::regclass
        and d.objid = t.oid
        and d.refclassid = 'pg_extension'::regclass
        and d.deptype = 'e'
        and x.extnamespace = t.typnamespace
    )
),
reject_use as (
  select
    ic.relid,
    ic.attname,
    ic.via_domain,
    ic.via_array,
    ic.via_composite,
    ic.via_range,
    re.oid as enum_oid,
    re.nspname,
    re.typname
  from integrity_column as ic
  join reject_enum as re on re.oid = ic.typid
)
select
  case
    when ru.via_domain then 'domain_column'
    when ru.via_array then 'array_column'
    when ru.via_composite then 'composite_column'
    when ru.via_range then 'range_column'
    else 'direct_column'
  end::text as branch,
  format('%I.%I.%I', n.nspname, c.relname, ru.attname)::text as object,
  format('column uses enum %I.%I, which has a reject label', ru.nspname, ru.typname)::text as detail
from reject_use as ru
join pg_class as c on c.oid = ru.relid
join pg_namespace as n on n.oid = c.relnamespace
union all
select
  'unused_integrity_enum'::text,
  format('%I.%I', re.nspname, re.typname)::text,
  'enum in schema integrity has a reject label'::text
from reject_enum as re
where re.nspname = 'integrity'
  and not exists (
    select 1
    from reject_use as ru
    where ru.enum_oid = re.oid
  )
) as v where v.branch = 'direct_column'
$q$, 'MT-6.direct_column: fires');
rollback to savepoint mt;
savepoint mt;
